          "invoice_date",
          "currency",
          "net_amount",
          "vat_rate",
          "vat_amount",
          "total_amount",
          "confidence",
          "notes"
        ],
        "properties": {
          "supplier_name": {
            "type": [
              "string",
              "null"
            ],
            "description": "Legal name of the company that issued the invoice"
          },
          "supplier_vat_id": {
            "type": [
              "string",
              "null"
            ],
            "description": "Supplier VAT ID (USt-IdNr. / UID), without spaces"
          },
          "invoice_number": {
            "type": [
              "string",
              "null"
            ],
            "description": "Invoice number exactly as printed"
          },
          "invoice_date": {
            "type": [
              "string",
